// @whimtex-effect Learn/Final Tint
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @param color _Tint = #FFFFFF
// @param float _Brightness = 1 [0 .. ~3]


float LearnHash(float2 p){ return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
float LearnNoise(float2 p, float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 ApplyFX(float2 uv,float4 color){

return float4(color.rgb*_Tint.rgb*_Brightness,color.a*_Tint.a*_Opacity);
}

// @whimtex-effect Learn/Liquid Sphere
// @control(_Opacity)
// @param float _Opacity = 1 [0 .. 1]
// @group(Placement)
// @param point _Center = (0.5, 0.5)
// @param float2 _Scale = (1, 1)
// @param float _Angle = 0 [-180 .. 180]
// @endgroup
// @group(Surface; _Part)
// @param hidden enum _Part = Body {Body:0, Rim:1, Reflection:2}
// @param float _Radius = 0.45 [0.1 .. 0.49]
// @param float _RimWidth = 0.026 [0.001 .. 0.12]
// @param float _Softness = 0.001 [0 .. 0.04]
// @param float _BodyOpacity = 1 [0 .. 1]
// @param float _Fresnel = 2.8 [0.3 .. 8]
// @endgroup
// @group(Reflection)
// @param point _Highlight = (0.67, 0.27)
// @param float2 _HighlightSize = (0.12, 0.065)
// @param float _HighlightAngle = 40 [-180 .. 180]
// @param float _Brightness = 0.8 [0 .. 2]
// @endgroup

float LearnHash(float2 p){ return frac(sin(dot(p,float2(127.1,311.7)))*43758.5453); }
float LearnNoise(float2 p, float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float LearnFbm(float2 p,float seed){
 fnl_state s=fnlCreateState((int)seed);s.noise_type=FNL_NOISE_OPENSIMPLEX2S;s.frequency=1;
 s.fractal_type=FNL_FRACTAL_FBM;s.octaves=3;s.gain=.42;
 return fnlGetNoise2D(s,p.x,p.y)*.5+.5;
}
float2 LearnRotate(float2 p,float angle){float c=cos(radians(angle)),s=sin(radians(angle));return float2(c*p.x-s*p.y,s*p.x+c*p.y);}
float LearnEdge(float d,float softness){float w=max(fwidth(d),max(softness,.00001));return 1-smoothstep(-w,w,d);}
float LearnGauss(float x){return exp(-x*x);}

float4 ApplyFX(float2 uv,float4 color){
float2 p=LearnRotate(LayerToLocal(uv)-_Center,-_Angle)/max(abs(_Scale),.001);

float r=length(p)/max(_Radius,.001);float edge=LearnEdge(length(p)-_Radius,_Softness);
float z=sqrt(saturate(1-r*r));float rim=pow(saturate(1-z),_Fresnel);
float body=saturate(.42+.28*z+.25*p.y/_Radius);
float2 h=LearnRotate(p-(_Highlight-.5),-_HighlightAngle)/max(_HighlightSize,.001);
float spec=exp(-dot(h,h)*2)*_Brightness;
if(_Part<.5)return float4(body.xxx,edge*_BodyOpacity*_Opacity);
if(_Part<1.5){float coverage=max(rim*.7,exp(-max(0,_Radius-length(p))/_RimWidth)*.75);return float4(1,1,1,edge*coverage*_Opacity);}
return float4(1,1,1,edge*saturate(spec)*_Opacity);
}

